for _ in range(int(input())):
	(n, h, d, j, l) = map(int, input().split())
	(flag, count) = (1, 0)
	l -= 1
	for _ in range(n):
		(t, s) = map(int, input().split())
		if t == 1 and flag:
			if h - d <= s:
				count += 1
			elif l:
				count += 1
				l -= 1
			else:
				flag = 0
				continue
		elif t == 2 and flag:
			if s - j <= 0:
				count += 1
			elif l:
				count += 1
				l -= 1
			else:
				flag = 0
	print(count)
